def default_question(ch, slot: int):
    term, desc = ch['definitions'][min(slot-1, len(ch['definitions'])-1)]
    formula, note = ch['formulas'][min(slot-1, len(ch['formulas'])-1)]
    if slot == 1:
        return {'question':f'下列關於「{term}」的敘述，最精確的定義是什麼？','answer':desc,'explanation':f'判斷關鍵是先固定本章名詞。「{term}」在本書指：{desc}'}
    if slot == 2:
        return {'question':f'關係式「{formula}」應如何解讀，使用時最重要的條件是什麼？','answer':note,'explanation':f'公式不能脫離模型條件。這個關係在本章的用途與限制是：{note}'}
    if slot == 3:
        return {'question':f'機制題：用一句完整因果鏈說明「{ch["title"]}」的核心經濟直覺。','answer':ch['intuition'][0],'explanation':ch['intuition'][0]+' '+ch['intuition'][-1]}
    if slot == 4:
        return {'question':f'綜合判斷：看到「{ch["figure"][0]}」這類題目時，最穩健的分析順序是什麼？','answer':'先固定市場與模型假設，再追蹤廠商誘因與最佳反應，最後比較價格、產量、利潤、進入或福利結果。','explanation':'產業經濟學的模型不能只背結論；同一市場在不同競爭變數、時序、差異化與進入條件下可能得到不同結果。'}
    trap = ch['traps'][0]
    return {'question':f'常見陷阱判斷：「{trap}」為什麼不能直接成立？','answer':'因為它忽略本章的市場界定、模型假設或反事實條件，不能把條件性結果寫成無條件結論。','explanation':f'本章把這句列為常見錯誤。作答時回到「{ch["exam"][0]}」，並把必要條件寫完整。'}


def build_questions():
    items=[]
    for ch in CHAPTERS:
        for slot in range(1,6):
            qid=f'{ch["id"]}-q{slot:02d}'
            item={'id':qid,'chapterId':ch['id'],**default_question(ch,slot)}
            if qid in OVERRIDES:
                item.update(OVERRIDES[qid])
            items.append(item)
    assert len(items)==100
    assert len({x['id'] for x in items})==100
    return items
